package git

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// SupportedHooks lists the standard Git hooks managed by HookCraft.
var SupportedHooks = []string{
	"pre-commit",
	"commit-msg",
	"pre-push",
	"post-commit",
}

const (
	hookcraftMarker = "# Generated by HookCraft"
)

// GenerateHookScript returns the shell script content for a hook shim.
func GenerateHookScript(hookName string) string {
	return fmt.Sprintf(`#!/bin/sh
%s - do not edit directly
# Ultra-fast Git hook orchestrator: https://github.com/alexandrmotologa/hookcraft

if command -v hookcraft >/dev/null 2>&1; then
    exec hookcraft run %s "$@"
fi

# Fallback: check if hookcraft exists in local project bin or system paths
if [ -f "./bin/hookcraft" ]; then
    exec ./bin/hookcraft run %s "$@"
elif [ -f "./hookcraft" ]; then
    exec ./hookcraft run %s "$@"
fi

echo "[hookcraft] Error: 'hookcraft' executable not found in PATH." >&2
echo "[hookcraft] Please install hookcraft or ensure it is in your PATH." >&2
exit 1
`, hookcraftMarker, hookName, hookName, hookName)
}

// InstallHooks installs hookcraft shims into the repository's hooks directory.
func (r *Runner) InstallHooks(hooks []string) ([]string, error) {
	hooksDir := filepath.Join(r.GitDir, "hooks")
	if err := os.MkdirAll(hooksDir, 0755); err != nil {
		return nil, fmt.Errorf("failed to create hooks directory: %w", err)
	}

	if len(hooks) == 0 {
		hooks = SupportedHooks
	}

	installed := make([]string, 0, len(hooks))

	for _, hook := range hooks {
		hookPath := filepath.Join(hooksDir, hook)
		backupPath := filepath.Join(hooksDir, hook+".hookcraft-backup")

		// Check if file exists
		if _, err := os.Stat(hookPath); err == nil {
			content, err := os.ReadFile(hookPath)
			if err == nil && strings.Contains(string(content), hookcraftMarker) {
				// Already installed by hookcraft, overwrite with latest shim
			} else {
				// Backup existing foreign hook
				_ = os.Rename(hookPath, backupPath)
			}
		}

		scriptContent := GenerateHookScript(hook)
		// Write file with executable permissions (0755)
		if err := os.WriteFile(hookPath, []byte(scriptContent), 0755); err != nil {
			return installed, fmt.Errorf("failed to write hook %s: %w", hook, err)
		}

		installed = append(installed, hook)
	}

	return installed, nil
}

// UninstallHooks removes hookcraft shims and restores previous backups.
func (r *Runner) UninstallHooks(hooks []string) ([]string, error) {
	hooksDir := filepath.Join(r.GitDir, "hooks")
	if len(hooks) == 0 {
		hooks = SupportedHooks
	}

	removed := make([]string, 0, len(hooks))

	for _, hook := range hooks {
		hookPath := filepath.Join(hooksDir, hook)
		backupPath := filepath.Join(hooksDir, hook+".hookcraft-backup")

		if _, err := os.Stat(hookPath); err == nil {
			content, err := os.ReadFile(hookPath)
			if err == nil && strings.Contains(string(content), hookcraftMarker) {
				if err := os.Remove(hookPath); err == nil {
					removed = append(removed, hook)
				}
			}

			// Restore backup if it exists
			if _, err := os.Stat(backupPath); err == nil {
				_ = os.Rename(backupPath, hookPath)
			}
		}
	}

	return removed, nil
}

// GetHookStatus returns a map of hook names and whether they are installed by HookCraft.
func (r *Runner) GetHookStatus() (map[string]bool, error) {
	hooksDir := filepath.Join(r.GitDir, "hooks")
	status := make(map[string]bool)

	for _, hook := range SupportedHooks {
		hookPath := filepath.Join(hooksDir, hook)
		content, err := os.ReadFile(hookPath)
		if err != nil {
			status[hook] = false
			continue
		}
		status[hook] = strings.Contains(string(content), hookcraftMarker)
	}

	return status, nil
}
